mapper.select:
select * from (select DISTINCT * from (SELECT rild.PRODID prodid, rild.PROD_NAME prodName, rild.REP_TYPE repType, rfp.NAME repTypeName, rild.REP_NAME repName, case when rild.START_DATE is null or rild.START_DATE = rild.END_DATE then to_char(rild.END_DATE,'yyyy-mm-dd') else to_char(rild.START_DATE,'yyyy-mm-dd') || '--'||to_char(rild.END_DATE,'yyyy-mm-dd') end reportDate, rild.REVEAL_END_DATE revealEndDate, rild.EXEC_STATUS execStatus, to_char(rild.STR_EXEC_DATE,'yyyy-mm-dd hh24:mi:ss') startExecDate, to_char(rild.END_EXEC_DATE,'yyyy-mm-dd hh24:mi:ss') endExecDate, decode(rild.EXEC_STATUS,'01','01','02') execResult, rild.EXEC_RESULT execResultExplain, ril.JOB_NAME jobName FROM REP_INSTALL_LOG_DETAIL rild INNER JOIN REP_INSTALL_LOG ril ON rild.JOB_ID = ril.JOB_ID AND ril.STATUS = #{status,jdbcType=VARCHAR} LEFT JOIN REP_INFO ri ON rild.REP_ID = ri.REP_ID LEFT JOIN REP_FTP_PATH rfp ON ri.REPORT_CATEGORY = rfp.ID
LEFT JOIN ( SELECT rep_id, LISTAGG(ERRORMSG, '；') as errormsg FROM REP_CHECK_ERRMSG GROUP BY rep_id ) check on check.rep_id = rild.id WHERE rild.STATUS = #{status,jdbcType=VARCHAR}
AND rild.JOB_ID in
#{item}
AND rild.PRODID IN
#{item}
AND rild.REP_NAME like '%' || #{repName,jdbcType=VARCHAR} || '%'
AND rild.EXEC_STATUS IN
#{item}
AND rild.EXEC_STATUS IN
#{item}
AND to_char(rild.STR_EXEC_DATE,'yyyy-mm-dd') >= #{valDateBegin,jdbcType=VARCHAR}
AND to_char(rild.END_EXEC_DATE,'yyyy-mm-dd') <= #{valDateEnd,jdbcType=VARCHAR}
AND ri.REPORT_CATEGORY IN
#{item}
AND to_char(rild.REVEAL_END_DATE,'yyyy-mm-dd') >= #{revealEndDateBegin,jdbcType=VARCHAR}
AND to_char(rild.REVEAL_END_DATE,'yyyy-mm-dd') <= #{revealEndDateEnd,jdbcType=VARCHAR}
order by rild.UPDATE_TIME desc))where 1=1
